def make_emotion_and_topic_vec(vocab):
    emo_vec_maker = EmotionVectorMaker(use_intensity=False)
    empath_7d = Empath7DVectorMaker()

    with open('processed_data/vocab_vectors.jsonl', 'w', encoding='utf-8') as f:
        for word in tqdm(vocab):
            emotion_vec = emo_vec_maker.getEmotionVecFor_Word(word)
            topic_vec = empath_7d.getEmapthVector(word)

            data = {
                "word": word,
                "emotion_vec": emotion_vec,
                "topic_vec": topic_vec
            }
            
            # Convert to string and write as a new line
            f.write(json.dumps(data) + '\n')

def load_emotion_and_topic_vec():
    emotion_dicts = {}
    topic_dicts = {}

    try:
        with open('processed_data/vocab_vectors.jsonl', 'r', encoding='utf-8') as f:
            for line in f:
                # Parse the JSON line back into a Python dict
                data = json.loads(line)
                
                word = data['word']
                
                # Assign the vectors to their respective dictionaries
                emotion_dicts[word] = data['emotion_vec']
                topic_dicts[word] = data['topic_vec']
                
        print(f"Successfully loaded {len(emotion_dicts)} words.")
        return emotion_dicts, topic_dicts

    except FileNotFoundError:
        print("Error: The file 'vocab_vectors.jsonl' was not found.")
        return {}, {}
    
def combine_emotion_and_topic_vec():
    vec_combiner = EmotionConditionedTopicVectorMaker()
    with open('processed_data/vocab_using_w2v_vectors.jsonl', 'r', encoding='utf-8') as infile, open('processed_data/vocab_w2v_combined_vectors.jsonl', 'w') as outfile:
        for line in infile:
            data = json.loads(line)
            word = data['word']
            
            e_vec = data['emotion_vec']
            t_vec = data['w2v_topic_vec']

            emotion_conditioned_vec = vec_combiner.get_emotion_conditioned_topic_vector(topic_vec=t_vec, emotion_vec=e_vec)

            out_data = {
                "word": word,
                "w2v_emotion_conditioned_topic_vec" : emotion_conditioned_vec
            }

            outfile.write(json.dumps(out_data) + '\n')

def review_vocab_combined_vectors(path, access, vec_name, sample_size=1000):
    vectors = []
    words = []

    with open(path, 'r', encoding='utf-8') as f:
        for i, line in enumerate(f):
            data = json.loads(line)
            vectors.append(data[vec_name])
            words.append(data[access])
            if i >= sample_size: # Sampling to keep it fast
                break
    
    vec_array = np.array(vectors)

    # 1. Standard Deviation (Internal Variation)
    # High std dev = vector is "peaky" (strongly associated with one topic)
    # Low std dev = vector is "flat" (neutral/spread out)
    avg_std = np.mean(np.std(vec_array, axis=1))

    # 2. Cosine Similarity (Inter-word Variation)
    # 1.0 means vectors are identical; 0.0 means they are completely different.
    # We want a lower average similarity to indicate high variation.
    sim_matrix = cosine_similarity(vec_array)
    # Take only the upper triangle to avoid self-comparison
    triu_indices = np.triu_indices_from(sim_matrix, k=1)
    avg_similarity = np.mean(sim_matrix[triu_indices])

    print(f"--- Analysis for {len(words)} words ---")
    print(f"Average Internal Variance (Std Dev): {avg_std:.6f}")
    print(f"Average Inter-word Similarity: {avg_similarity:.6f}")
    
    if avg_similarity > 0.95:
        print("Warning: High similarity. Most vectors look almost identical.")
    else:
        print("Success: Good variation detected between word vectors.")
    

def book_description_level():
    vector_maker = EmotionConditionedTopicVectorMaker()

    with open('processed_data/book_vectors_attempt_1.jsonl', 'r', encoding='utf-8') as infile, open('processed_data/book_conditioned_vectors.jsonl', 'w') as outfile:
        for line in infile:
            data = json.loads(line)
            isbn = data['isbn']
            emotion_vec = data['emotion']
            topic_vec = data['tf_idf']
            conditioned_vec = vector_maker.get_emotion_conditioned_topic_vector(topic_vec, emotion_vec)

            out_data = {
                "isbn": isbn,
                "emotion_conditioned_topic_vec" : conditioned_vec
            }

            outfile.write(json.dumps(out_data) + '\n')


def make_emotion_and_w2v_topic_vec(vocab):
    emo_vec_maker = EmotionVectorMaker(use_intensity=False)
    print("Emotion Vector Maker made")

    book_descriptions = dict(get_descriptions("processed_data/books_with_subjects_1.jsonl")) 
    all_descriptions = list(book_descriptions.values())
    print("descriptions retrieved")

    w2v_vec_maker = W2VVectorMaker(all_descriptions=all_descriptions)
    print("Word2Vec Maker made")

    with open('processed_data/vocab_using_w2v_vectors.jsonl', 'w', encoding='utf-8') as f:
        for word in tqdm(vocab):
            emotion_vec = emo_vec_maker.getEmotionVecFor_Word(word)
            topic_vec = w2v_vec_maker.get_vector(word)

            data = {
                "word": word,
                "emotion_vec": emotion_vec,
                "w2v_topic_vec": topic_vec
            }            
            # Convert to string and write as a new line
            f.write(json.dumps(data) + '\n')

